/**
 * Property-based Playwright tests for the player view.
 *
 * Uses fast-check to randomly generate valid player states and verify
 * that the 10 documented UI invariants hold across the full state space.
 * Existing hand-crafted tests in player-view-states.spec.ts remain as
 * pinned regression cases.
 */
import { test, expect } from "../fixtures/base.fixture";
import type { Page } from "@playwright/test";
import fc from "fast-check";
import {
  playerStateArb,
  buildSnapshot,
  buildPlayerUrl,
  CONTEXT,
  EX_ID,
  type PlayerState,
} from "../helpers/arbitraries";

const NUM_RUNS = Number(process.env["PROP_RUNS"] ?? 30);

// ── Mock installer (matches existing pattern) ────────────────────────

async function installMocks(
  page: Page,
  state: PlayerState,
): Promise<void> {
  const snap = buildSnapshot(state);
  const decisions = snap.decisions ?? [];

  await page.route(`**/api/exercises/${EX_ID}/engine/snapshot`, (route) =>
    route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify(snap),
    }),
  );
  await page.route(`**/api/exercises/${EX_ID}/engine/context`, (route) =>
    route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify(CONTEXT),
    }),
  );
  await page.route("**/api/decisions*", async (route) => {
    if (route.request().url().includes("/engine/")) {
      await route.fallback();
      return;
    }
    await route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify([]),
    });
  });
  await page.route(
    `**/api/exercises/${EX_ID}/engine/decisions`,
    async (route) => {
      if (route.request().method() === "GET") {
        await route.fulfill({
          status: 200,
          contentType: "application/json",
          body: JSON.stringify(decisions),
        });
      } else {
        await route.fallback();
      }
    },
  );
  await page.route("**/ws?*", (route) => route.abort("connectionrefused"));
  await page.route("**/ws", (route) => route.abort("connectionrefused"));
  await page.route("**/api/domain-configs", (route) =>
    route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify([]),
    }),
  );
}

// ── Helpers ──────────────────────────────────────────────────────────

function isDecisionMakerRole(role: string): boolean {
  return role === "co";
}

function hasOpenDecisionForRole(state: PlayerState): boolean {
  if (state.decisions.length === 0) return false;
  const dec = state.decisions[0];
  if (dec.target_roles.length === 0) return true;
  return dec.target_roles.includes(state.role);
}

function hasRecommendations(state: PlayerState): boolean {
  if (state.decisions.length === 0) return false;
  return Object.keys(state.decisions[0].recommendations).length > 0;
}

function shouldShowScore(state: PlayerState): boolean {
  return state.score !== null && state.phase !== "briefing";
}

// ── Properties ──────────────────────────────────────────────────────

test.describe("Property: player view invariants @property", () => {
  test("P1: header always visible", async ({ page }) => {
    await fc.assert(
      fc.asyncProperty(playerStateArb, async (state) => {
        await installMocks(page, state);
        await page.goto(buildPlayerUrl(state));

        await expect(page.locator(".player-header__title")).toBeVisible();
        await expect(page.locator("tfc-phase-badge")).toBeVisible();
      }),
      { numRuns: NUM_RUNS },
    );
  });

  test("P2: phase badge matches state", async ({ page }) => {
    await fc.assert(
      fc.asyncProperty(playerStateArb, async (state) => {
        await installMocks(page, state);
        await page.goto(buildPlayerUrl(state));

        await expect(page.locator("tfc-phase-badge")).toContainText(state.phase);
      }),
      { numRuns: NUM_RUNS },
    );
  });

  test("P3: turn banner visible iff score exists and not briefing", async ({ page }) => {
    await fc.assert(
      fc.asyncProperty(playerStateArb, async (state) => {
        await installMocks(page, state);
        await page.goto(buildPlayerUrl(state));

        const banner = page.locator("tfc-turn-banner");
        if (shouldShowScore(state)) {
          await expect(banner).toBeVisible();
          await expect(banner).toContainText(`Turn ${state.score!.turn_number}`);
        } else {
          await expect(banner).not.toBeVisible();
        }
      }),
      { numRuns: NUM_RUNS },
    );
  });

  test("P4: score bar visible iff score exists and not briefing", async ({ page }) => {
    await fc.assert(
      fc.asyncProperty(playerStateArb, async (state) => {
        await installMocks(page, state);
        await page.goto(buildPlayerUrl(state));

        const scoreBar = page.locator("tfc-score-bar");
        if (shouldShowScore(state)) {
          await expect(scoreBar).toBeVisible();
        } else {
          await expect(scoreBar).not.toBeVisible();
        }
      }),
      { numRuns: NUM_RUNS },
    );
  });

  test("P5: events card shows only running and completed events", async ({ page }) => {
    await fc.assert(
      fc.asyncProperty(playerStateArb, async (state) => {
        await installMocks(page, state);
        await page.goto(buildPlayerUrl(state));

        for (const ev of state.events) {
          const text = page.getByText(ev.title);
          if (ev.lifecycle === "scheduled") {
            await expect(text).not.toBeVisible();
          } else {
            await expect(text).toBeVisible();
          }
        }
      }),
      { numRuns: NUM_RUNS },
    );
  });

  test("P6: issues card shows only released issues", async ({ page }) => {
    await fc.assert(
      fc.asyncProperty(playerStateArb, async (state) => {
        await installMocks(page, state);
        await page.goto(buildPlayerUrl(state));

        for (const iss of state.issues) {
          const text = page.getByText(iss.title);
          if (iss.released) {
            await expect(text).toBeVisible();
          } else {
            await expect(text).not.toBeVisible();
          }
        }
      }),
      { numRuns: NUM_RUNS },
    );
  });

  test("P7: decision panel visible iff open decision matches role", async ({ page }) => {
    await fc.assert(
      fc.asyncProperty(playerStateArb, async (state) => {
        await installMocks(page, state);
        await page.goto(buildPlayerUrl(state));

        const panel = page.locator("tfc-decision-panel");
        if (hasOpenDecisionForRole(state)) {
          await expect(panel).toBeAttached();
        } else {
          await expect(panel).not.toBeVisible();
        }
      }),
      { numRuns: NUM_RUNS },
    );
  });

  test("P8: advisor prefix shown iff advisor role with open decision", async ({ page }) => {
    await fc.assert(
      fc.asyncProperty(
        playerStateArb.filter((s) => hasOpenDecisionForRole(s)),
        async (state) => {
          await installMocks(page, state);
          await page.goto(buildPlayerUrl(state));

          const advisorPrefix = page.getByText("[Advisor]");
          if (isDecisionMakerRole(state.role)) {
            await expect(advisorPrefix).not.toBeVisible();
          } else {
            await expect(advisorPrefix).toBeVisible();
          }
        },
      ),
      { numRuns: NUM_RUNS },
    );
  });

  test("P9: advisor bubbles visible iff DM + recs exist", async ({ page }) => {
    await fc.assert(
      fc.asyncProperty(
        playerStateArb.filter((s) => hasOpenDecisionForRole(s)),
        async (state) => {
          await installMocks(page, state);
          await page.goto(buildPlayerUrl(state));

          const bubbles = page.locator("tfc-advisor-bubbles");
          if (isDecisionMakerRole(state.role) && hasRecommendations(state)) {
            await expect(bubbles).toBeVisible();
          } else {
            await expect(bubbles).not.toBeVisible();
          }
        },
      ),
      { numRuns: NUM_RUNS },
    );
  });

  test("P10: context panel shows briefing when loaded", async ({ page }) => {
    await fc.assert(
      fc.asyncProperty(playerStateArb, async (state) => {
        await installMocks(page, state);
        await page.goto(buildPlayerUrl(state));

        await expect(
          page.getByText("You are aboard the USS Sentinel."),
        ).toBeVisible();
      }),
      { numRuns: NUM_RUNS },
    );
  });
});

