 1→// apps/tfc/frontend/src/app/features/player/role-card.types.ts
 2→import type { ActiveDecision } from "../../core/decision-api.service";
 3→import type { RoleDef } from "../../core/scenario-api.service";
 4→import type { EventSnapshot } from "../../core/generated/state-changes.types";
 5→
 6→/** Extract the roleId from a recommendation key ("participantId:roleId" or bare "roleId"). */
 7→export function extractRecRoleId(key: string): string {
 8→  const colonIdx = key.indexOf(":");
 9→  return colonIdx !== -1 ? key.slice(colonIdx + 1) : key;
10→}
11→
12→export interface AdvisorRec {
13→  roleId: string;
14→  roleLabel: string;
15→  selection: string | null; // option label, or null if pending
16→}
17→
18→export interface RoleCard {
19→  roleId: string;
20→  roleLabel: string;
21→  playerType: "decision_maker" | "advisor";
22→  intel: string | null;
23→  decision: ActiveDecision | null;
24→  status: "intel" | "active" | "done";
25→  advisorRecs: AdvisorRec[];
26→}
27→
28→export function buildRoleCards(
29→  roles: RoleDef[],
30→  event: EventSnapshot | null,
31→  decision: ActiveDecision | null,
32→  submittedRoles: Set<string>,
33→  showDecisionMaker: boolean,
34→): RoleCard[] {
35→  if (!event && !decision) return [];
36→  const roleDescs = event?.role_descriptions ?? {};
37→  const targetRoles = decision?.target_roles ?? [];
38→
39→  return roles
40→    .filter((role) => {
41→      if (role.player_type === "decision_maker" && !showDecisionMaker)
42→        return false;
43→      const hasIntel = roleDescs[role.id] != null;
44→      const hasDecision = targetRoles.includes(role.id);
45→      return hasIntel || hasDecision;
46→    })
47→    .map((role) => {
48→      const hasDecision = targetRoles.includes(role.id);
49→      const isDone = hasDecision && submittedRoles.has(role.id);
50→      const advisorRecs: AdvisorRec[] = [];
51→
52→      if (role.player_type === "decision_maker" && decision) {
53→        const advisorTargets = targetRoles.filter((rid) => rid !== role.id);
54→        for (const advisorRoleId of advisorTargets) {
55→          const advisorRole = roles.find((r) => r.id === advisorRoleId);
56→          const recEntry = Object.entries(
57→            decision.recommendations || {},
58→          ).find(([key]) => extractRecRoleId(key) === advisorRoleId);
59→          const optionId = recEntry?.[1] ?? null;
60→          const optionLabel = optionId
61→            ? (decision.options.find((o) => o.id === optionId)?.label ?? optionId)
62→            : null;
63→          advisorRecs.push({
64→            roleId: advisorRoleId,
65→            roleLabel: advisorRole?.label ?? advisorRoleId,
66→            selection: optionLabel,
67→          });
68→        }
69→      }
70→
71→      const playerType =
72→        role.player_type === "decision_maker" || role.player_type === "advisor"
73→          ? role.player_type
74→          : "advisor"; // fallback — should never happen with valid scenario data
75→
76→      return {
77→        roleId: role.id,
78→        roleLabel: role.label,
79→        playerType,
80→        intel: roleDescs[role.id] ?? null,
81→        decision: hasDecision ? decision : null,
82→        status: hasDecision ? (isDone ? "done" : "active") : "intel",
83→        advisorRecs,
84→      } satisfies RoleCard;
85→    });
86→}
